def _count_tool_issues(tool_runner, file_path: str) -> Optional[int]:
    """Run a tool on a single file and return the number of issues found.

    Returns None if the tool failed for reasons other than not being installed.
    ToolNotFoundError is re-raised so callers can distinguish unavailability.
    """
    try:
        diags = tool_runner([file_path])
        return len(diags)
    except ToolNotFoundError:
        raise
    except Exception as e:
        logger.warning("Tool issue count failed for %s on %s: %s", tool_runner.__name__, file_path, e)
        return None
>>>>

And in `evaluate_fix`, immediately after assigning each count, guard for `None` and convert to UNEVALUABLE rather than proceeding with arithmetic.

In `_create_sandbox`, after copying source files, walk from `common` to `tmpdir` and copy any `__init__.py` files found in intermediate directories:
# After the copy loop, copy __init__.py files for package structure
for dirpath, dirnames, filenames in os.walk(common):
    if "__init__.py" in filenames:
        rel = os.path.relpath(dirpath, common)
        init_dst = os.path.join(tmpdir, rel, "__init__.py")
        if not os.path.exists(init_dst):
            init_src = os.path.join(dirpath, "__init__.py")
            os.makedirs(os.path.dirname(init_dst), exist_ok=True)
            shutil.copy2(init_src, init_dst)
